@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/geist";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --font-heading: var(--font-sans);
  --font-sans: "Geist Variable", sans-serif;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

:root {
  --radius: 0.5rem;
  --background: oklch(0.99 0.003 300);
  --foreground: oklch(0.17 0.02 300);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.17 0.02 300);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.17 0.02 300);
  --primary: oklch(0.58 0.19 40);
  --primary-foreground: oklch(0.99 0.003 300);
  --secondary: oklch(0.95 0.012 300);
  --secondary-foreground: oklch(0.25 0.05 300);
  --muted: oklch(0.96 0.008 300);
  --muted-foreground: oklch(0.5 0.025 300);
  --accent: oklch(0.94 0.02 300);
  --accent-foreground: oklch(0.25 0.05 300);
  --destructive: oklch(0.55 0.22 25);
  --border: oklch(0.91 0.012 300);
  --input: oklch(0.91 0.012 300);
  --ring: oklch(0.68 0.15 40);
  --chart-1: oklch(0.65 0.19 40);
  --chart-2: oklch(0.5 0.16 300);
  --chart-3: oklch(0.6 0.12 200);
  --chart-4: oklch(0.75 0.15 80);
  --chart-5: oklch(0.4 0.1 320);
  --sidebar: oklch(0.97 0.006 300);
  --sidebar-foreground: oklch(0.17 0.02 300);
  --sidebar-primary: oklch(0.58 0.19 40);
  --sidebar-primary-foreground: oklch(0.99 0.003 300);
  --sidebar-accent: oklch(0.93 0.02 300);
  --sidebar-accent-foreground: oklch(0.25 0.05 300);
  --sidebar-border: oklch(0.91 0.012 300);
  --sidebar-ring: oklch(0.68 0.15 40);
}

.dark {
  --background: oklch(0.16 0.02 300);
  --foreground: oklch(0.96 0.01 60);
  --card: oklch(0.2 0.025 300);
  --card-foreground: oklch(0.96 0.01 60);
  --popover: oklch(0.2 0.025 300);
  --popover-foreground: oklch(0.96 0.01 60);
  --primary: oklch(0.7 0.17 42);
  --primary-foreground: oklch(0.16 0.02 300);
  --secondary: oklch(0.27 0.04 300);
  --secondary-foreground: oklch(0.96 0.01 60);
  --muted: oklch(0.25 0.03 300);
  --muted-foreground: oklch(0.72 0.03 300);
  --accent: oklch(0.3 0.05 300);
  --accent-foreground: oklch(0.96 0.01 60);
  --destructive: oklch(0.68 0.19 25);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.6 0.15 42);
  --chart-1: oklch(0.7 0.17 42);
  --chart-2: oklch(0.62 0.16 300);
  --chart-3: oklch(0.7 0.12 200);
  --chart-4: oklch(0.8 0.14 80);
  --chart-5: oklch(0.55 0.12 320);
  --sidebar: oklch(0.19 0.025 300);
  --sidebar-foreground: oklch(0.96 0.01 60);
  --sidebar-primary: oklch(0.7 0.17 42);
  --sidebar-primary-foreground: oklch(0.16 0.02 300);
  --sidebar-accent: oklch(0.27 0.04 300);
  --sidebar-accent-foreground: oklch(0.96 0.01 60);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.6 0.15 42);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  html {
    @apply font-sans;
  }
}
